package it.math1;


public class CalcoliMath {

	public static void main(String[] args) {
		// TODO Auto-generated method 

		// stampa il valore assoluto di un numero
		int x = -5;
		System.out.println("valore assoluto : "+Math.abs(x));
		//numero alla potonza
		int num = -6;
		System.out.println( "numero elevato : "+Math.pow(num,2));
		// radice quadrata
		
		int numero = 64;
		System.out.println( "Radice Quadrata Di un  numero : "+Math.sqrt(numero));

	}

}
